      const ref = this.id ? `steps.${this.id}.outputs.${name}` : "";
      this.outputs[name] = ref ? `\${{ ${ref} }}` : "";
      this.rawOutputs[name] = new StepOutputRef(ref);
    }
    this.rawOutcome = new StepOutputRef(this.id ? `steps.${this.id}.outcome` : "");
