/**
 * The colour a run keeps once its ending reached the thread.
 *
 * The comment heals the thread, and the run's colour then has to carry what the
 * comment cannot. Two shapes are green: a step that came back — every ordinary run and
 * every soft stop — and an agent failure whose notice landed, which has said
 * everything there is to say and whose red run would only repeat that news in
 * Notifications. Every other shape is red: the machinery failed inside the step (a
 * tools file it could not write, a `sudo` it was refused, an ending it could not
 * read), or atoma's own exit was a failure and the flag was never written, which is
 * the conservative direction.
 */
function colourForStepFailure(stepFailed: boolean, atomaFailed: boolean): void {
  if (!stepFailed || atomaFailed) return;
  console.error("The machinery failed, not the agent; the notice healed the thread, but the run stays red.");
  process.exitCode = 1;
}

